payload:
$ErrorActionPreference='Stop'
$candidates = @(
  'C:\Users\Xxkan\mhw-mods',
  'C:\Users\Xxkan\source\repos\mhw-mods',
  'C:\Users\Xxkan\Documents\GitHub\mhw-mods',
  'C:\Users\Xxkan\Desktop\mhw-mods'
)
$repo=$null
foreach($p in $candidates){ if(Test-Path (Join-Path $p '.git')){$repo=$p;break} }
if(-not $repo){
  $gitDirs=Get-ChildItem 'C:\Users\Xxkan' -Directory -Filter '.git' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 20
  foreach($g in $gitDirs){
    $p=$g.Parent.FullName
    try{
      $url=(git -C $p remote get-url origin 2>$null)
      if($url -match 'fengie/mhw-mods'){ $repo=$p; break }
    } catch {}
  }
}
if(-not $repo){ throw 'Canonical mhw-mods checkout not found.' }
Write-Output "REPO=$repo"
git -C $repo fetch --all --prune
Write-Output 'STATUS:'
git -C $repo status --short --branch
Write-Output 'BRANCHES:'
git -C $repo branch -vv
Write-Output 'REMOTE HEADS:'
git -C $repo ls-remote --heads origin
